{% set group = attribute(site, 'club-einstellungen') %}
{% set team_slug = 'erste' %} {# anpassen: erste/zweite/dritte/jugend/ah #}
{% set all_matches = attribute(group, 'spieltage_teams') %}

{% set matches = all_matches|length >= 1
  ? all_matches
    |filter(v => (attribute(v, 'team').value|default(attribute(v, 'team'))) == team_slug)
    |filter(v => attribute(v, 'date_nextmatch').timestamp > mb.microtime(true))
    |sort((a, b) => attribute(a, 'date_nextmatch').timestamp <=> attribute(b, 'date_nextmatch').timestamp)
  : []
%}

{% if matches|length > 0 %}
  {% set match = matches|first %}
  <p class="club-next">Nächstes Spiel</p>
  <div class="club-next-match">
    <div class="club-team-block">
      <p class="club-team-name">{{ match.heimmannschaft.title }}</p>
      {{ _self.logo(match.heimmannschaft) }}
    </div>
    <span class="club-vs-nextgame">vs</span>
    <div class="club-team-block">
      <p class="club-team-name">{{ match.auswaerts.title }}</p>
      {{ _self.logo(match.auswaerts) }}
    </div>
  </div>
  <div class="club-match-data"><div class="club-match-data__inner">
    <p>// {{ match.liga }}</p>
    <p>// {{ match.date_nextmatch.timestamp|date("d.m.Y") }} um {{ match.date_nextmatch.timestamp|date("H:i") }} Uhr</p>
    <p>// {{ mb.rwmb_meta('adresse_sportplatz', null, match.heimmannschaft.ID) }}</p>
  </div></div>
{% else %}
  <div class="club-match-data"><div class="club-match-data__inner">
    <p style="text-align:center">Aktuell sind keine Spiele geplant ...</p>
  </div></div>
{% endif %}

{% macro logo(post, size = 'medium') %}
  <img class="club-team-logo" src="{{ post.thumbnail[size].url }}" alt="{{ post.alt }}" title="{{ post.title }}">
{% endmacro %}
